class Program {
 [STAThread] public static void Main(string[] args) => AppBuilder.Configure<App>().UsePlatformDetect().WithInterFont().StartWithClassicDesktopLifetime(args);
}
class App : Application {
 public override void Initialize() { Styles.Add(new FluentTheme()); RequestedThemeVariant=ThemeVariant.Light; }
 public override void OnFrameworkInitializationCompleted() { if(ApplicationLifetime is IClassicDesktopStyleApplicationLifetime d) d.MainWindow=new Atelier(); base.OnFrameworkInitializationCompleted(); }
}
class Atelier : Window {
